            value = float(ozone)
            year = int(row.get("Year", "1973"))
            month = int(row["Month"])
            day = int(row["Day"])
            observed_date = date(year, month, day)
        except (KeyError, TypeError, ValueError, OverflowError):
            continue
        if value > 60:
            qualifying_dates.add(observed_date)

    longest = current = 0
    previous = None
    for observed_date in sorted(qualifying_dates):
        if previous is not None and (observed_date - previous).days == 1:
            current += 1
        else:
            current = 1
        longest = max(longest, current)
        previous = observed_date
    return longest

