"""Compute median day-0-to-day-20 weight gain by diet."""

from collections import defaultdict
from statistics import median


def solve(rows):
    """Return median paired weight gains, keyed by diet code.

    ``rows`` is an iterable of mappings whose values are strings and whose
    keys include ``Diet``, ``Chick``, ``Time``, and ``weight``. A chick
    contributes only when both day 0 and day 20 observations are present.
    """
    weights = {}
    for row in rows:
        day = row["Time"]
        if day not in ("0", "20"):
            continue
        key = (row["Diet"], row["Chick"])
        weights.setdefault(key, {})[day] = float(row["weight"])

    gains_by_diet = defaultdict(list)
    for (diet, _chick), observations in weights.items():
        if "0" in observations and "20" in observations:
            gains_by_diet[diet].append(observations["20"] - observations["0"])

    return {diet: median(gains) for diet, gains in gains_by_diet.items() if gains}

