from collections import defaultdict


def solve(rows):
    """Return annual peak-to-trough amplitudes for complete calendar years.

    Each row is a mapping with string values and ``time``/``value`` keys.
    Decimal times are assigned to the nearest month using round(time * 12),
    with month index zero corresponding to January of year zero.
    """
    monthly_values = defaultdict(dict)
    for row in rows:
        month_index = round(float(row["time"]) * 12)
        year, month = divmod(month_index, 12)
        monthly_values[year][month] = float(row["value"])

    amplitudes = {}
    for year, values in monthly_values.items():
        if len(values) == 12 and all(month in values for month in range(12)):
            amplitudes[str(year)] = max(values.values()) - min(values.values())

    return {year: amplitudes[year] for year in sorted(amplitudes, key=int)}

